							"x": 730,
							"y": 280
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false
		},
		"tabs": {
			"items": [
				{
					"label": "Overview",
					"layoutId": "layout_overview"
				},
				{
					"label": "Details",
					"layoutId": "layout_details"
				},
				{
					"label": "About",
					"layoutId": "layout_about"
				}
			]
		}
	},
	"applicationProperties": {
		"hideEdit": false
	}
}
